//! Known answers pinned from `spec` (generated by `bench/src/bin/kat.rs`, which checks
//! them against the dispatched backend), the SMHasher verification values, and
//! structural properties. Input byte `i` is `(i * 31 + 7) as u8`.
use lanehash::{hash128, hash64};

fn buf(n: usize) -> Vec<u8> {
    (0..n).map(|i| (i * 31 + 7) as u8).collect()
}

