/// SMHasher's verification value: low 32 bits of the hash of the concatenated hashes of
/// `key[..i]` (`key[i] = i`) under seed `256 - i`.
#[test]
fn smhasher_verification_values() {
    let mut key = [0u8; 256];
    let mut h64 = [0u8; 8 * 256];
    let mut h128 = [0u8; 16 * 256];
    for i in 0..256 {
        key[i] = i as u8;
        let seed = 256 - i as u64;
        h64[8 * i..8 * i + 8].copy_from_slice(&hash64(&key[..i], seed).to_le_bytes());
        h128[16 * i..16 * i + 16].copy_from_slice(&hash128(&key[..i], seed).to_le_bytes());
    }
    assert_eq!(hash64(&h64, 0) as u32, 0xd048_c22b, "lanehash64 verification value");
    assert_eq!(hash128(&h128, 0) as u32, 0xc2f3_9939, "lanehash128 verification value");
}

/// At every length the 128-bit output's low half is the 64-bit output, its high half
/// differs, and seed and length matter.
#[test]
fn structure() {
    let b = buf(1100);
    for n in 0..=64 {
        assert_eq!(hash128(&b[..n], 7), lanehash::short::short128(&b[..n], 7), "short path n={n}");
        assert_eq!(hash64(&b[..n], 7), lanehash::short::short64(&b[..n], 7), "short path n={n}");
    }
    for n in 1..=1100 {
        let (h, w) = (hash128(&b[..n], 7), hash64(&b[..n], 7));
        assert_eq!(h as u64, w, "n={n}");
        assert_ne!((h >> 64) as u64, w, "n={n}");
        assert_ne!(hash64(&b[..n], 7), hash64(&b[..n], 8), "seed n={n}");
        assert_ne!(hash64(&b[..n], 7), hash64(&b[..n - 1], 7), "length n={n}");
    }
}
